// cards_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) cards_by_keys(keys []string) ![]CardNode {
	rows := g.cards().where(load.in_keys('id', keys, .int)).all()!
	mut by_key := map[string]CardNode{}
	for row in rows {
		by_key[row.card.id.str()] = row
	}
	mut found := []CardNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'cards'
			}
		}
	}
	return found
}
